-- AlterTable: adds Document Numbering entries for the 8 second-batch
-- letter types (Non-Solicitation Agreement, Letter of Intent, Background
-- Verification Consent, Show-Cause Notice, Suspension Letter, Retirement
-- Letter, Internship Certificate, Employment Verification Letter) — see
-- letter-template-defaults.ts. Same rationale as the previous migration
-- (20260907050000): issueDocumentNumber() self-heals a missing key, so
-- this isn't strictly required for correctness, just gives every org a
-- polished label/format from day one instead of a generic fallback.
ALTER TABLE "organizations"
  ALTER COLUMN "documentNumbering" SET DEFAULT '{"employeeId":{"label":"Employee ID","format":"DP-{00000}","resetRule":"never","counter":0,"lastPeriodKey":null},"payslip":{"label":"Payslip","format":"PS-{DD_MM_YYYY}-{00001}","resetRule":"monthly","counter":0,"lastPeriodKey":null},"offerLetter":{"label":"Offer Letter","format":"OL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"appointmentLetter":{"label":"Appointment Letter","format":"AL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"experienceLetter":{"label":"Experience Letter","format":"EL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"relievingLetter":{"label":"Relieving Letter","format":"RL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"salaryCertificate":{"label":"Salary Certificate","format":"SC-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"fullFinalSettlement":{"label":"Full & Final Settlement","format":"FNF-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"experienceCertificate":{"label":"Experience Certificate","format":"EC-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"confirmationLetter":{"label":"Confirmation Letter","format":"CL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"probationExtensionLetter":{"label":"Probation Extension Letter","format":"PE-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"promotionLetter":{"label":"Promotion Letter","format":"PRL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"incrementLetter":{"label":"Increment Letter","format":"INC-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"transferLetter":{"label":"Transfer Letter","format":"TRL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"resignationAcceptance":{"label":"Resignation Acceptance Letter","format":"RA-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"terminationLetter":{"label":"Termination Letter","format":"TML-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"warningLetter":{"label":"Warning Letter","format":"WL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"nda":{"label":"Non-Disclosure Agreement","format":"NDA-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"nonCompeteAgreement":{"label":"Non-Compete Agreement","format":"NCA-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"nonSolicitationAgreement":{"label":"Non-Solicitation Agreement","format":"NSA-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"letterOfIntent":{"label":"Letter of Intent","format":"LOI-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"backgroundVerificationConsent":{"label":"Background Verification Consent","format":"BVC-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"showCauseNotice":{"label":"Show-Cause Notice","format":"SCN-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"suspensionLetter":{"label":"Suspension Letter","format":"SL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"retirementLetter":{"label":"Retirement Letter","format":"RTL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"internshipCertificate":{"label":"Internship Certificate","format":"IC-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"employmentVerificationLetter":{"label":"Employment Verification Letter","format":"EVL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null}}';

-- Backfill: merge the 8 new keys into every existing org's
-- documentNumbering additively — see 20260907050000's identical pattern.
UPDATE "organizations"
SET "documentNumbering" = "documentNumbering" || '{"nonSolicitationAgreement":{"label":"Non-Solicitation Agreement","format":"NSA-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"letterOfIntent":{"label":"Letter of Intent","format":"LOI-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"backgroundVerificationConsent":{"label":"Background Verification Consent","format":"BVC-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"showCauseNotice":{"label":"Show-Cause Notice","format":"SCN-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"suspensionLetter":{"label":"Suspension Letter","format":"SL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"retirementLetter":{"label":"Retirement Letter","format":"RTL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"internshipCertificate":{"label":"Internship Certificate","format":"IC-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null},"employmentVerificationLetter":{"label":"Employment Verification Letter","format":"EVL-{DD_MM_YYYY}-{00001}","resetRule":"yearly","counter":0,"lastPeriodKey":null}}'::jsonb
WHERE NOT ("documentNumbering" ? 'nonSolicitationAgreement');
